/**
 * Counts that are abandoned after their budget are bounded, and statement counts use {@link RepositoryConnection#size}.
 */
class BrowseListCountsTest {

	@Test
	void countsBeyondTheInFlightLimitAreAnsweredAsTimedOutWithoutRunning() throws Exception {
		BrowseList browseList = new BrowseList(1);
		CountDownLatch release = new CountDownLatch(1);
		CountDownLatch finished = new CountDownLatch(1);
		AtomicBoolean secondRan = new AtomicBoolean();
		try {
			Optional<Long> abandoned = browseList.withinBudget(() -> {
				try {
					// An abandoned remote count blocks in I/O and ignores the interrupt.
					while (!release.await(10, TimeUnit.SECONDS)) {
						// keep blocking
					}
					return 1L;
				} catch (InterruptedException e) {
					release.await(10, TimeUnit.SECONDS);
					return 1L;
				} finally {
					finished.countDown();
				}
			}, 50);
			Optional<Long> rejected = browseList.withinBudget(() -> {
				secondRan.set(true);
				return 2L;
			}, 1000);

			assertThat(abandoned).isEmpty();
			assertThat(rejected).as("no worker is free while the abandoned count still runs").isEmpty();
			assertThat(secondRan).isFalse();

			release.countDown();
			assertThat(finished.await(5, TimeUnit.SECONDS)).isTrue();
			Optional<Long> afterwards = Optional.empty();
			for (int attempt = 0; attempt < 50 && afterwards.isEmpty(); attempt++) {
				afterwards = browseList.withinBudget(() -> 3L, 1000);
				if (afterwards.isEmpty()) {
					Thread.sleep(20);
				}
			}
			assertThat(afterwards).as("the worker is free again once the abandoned count returns").contains(3L);
		} finally {
			release.countDown();
			browseList.shutdown();
		}
	}

	/**
	 * A count cancelled before its worker started never runs, so it must give its place back when it is cancelled:
	 * otherwise every such count lowers the limit for good.
	 */
	@Test
	void countsCancelledBeforeTheyStartGiveTheirPlaceBack() throws Exception {
		BrowseList browseList = new BrowseList(1);
		try {
			for (int attempt = 0; attempt < 50; attempt++) {
				// No budget at all: the count is cancelled at once, mostly before its worker starts it.
				assertThat(browseList.withinBudget(() -> 1L, 0)).isEmpty();
				Optional<Long> next = Optional.empty();
				for (int retry = 0; retry < 100 && next.isEmpty(); retry++) {
					next = browseList.withinBudget(() -> 2L, 1000);
					if (next.isEmpty()) {
						Thread.sleep(10);
					}
				}
				assertThat(next).as("attempt %d: the cancelled count gave its place back", attempt).contains(2L);
			}
		} finally {
			browseList.shutdown();
		}
	}

	@Test
	void requestsForTheSameCountShareOneRunningCount() throws Exception {
		BrowseList browseList = new BrowseList(8);
		ExecutorService requests = Executors.newFixedThreadPool(3);
		CountDownLatch started = new CountDownLatch(1);
		CountDownLatch release = new CountDownLatch(1);
		AtomicInteger runs = new AtomicInteger();
		CountDownLatch allowReload = new CountDownLatch(1);
		CountDownLatch reloadReady = new CountDownLatch(1);
		AtomicReference<Thread> reloadThread = new AtomicReference<>();
		Callable<Long> count = () -> {
			runs.incrementAndGet();
			started.countDown();
			release.await(10, TimeUnit.SECONDS);
			return 42L;
		};
		try {
			Future<Optional<Long>> first = requests.submit(() -> browseList.sharedWithinBudget("types", count, 5000));
			assertThat(started.await(5, TimeUnit.SECONDS)).isTrue();
			Future<Optional<Long>> reload = requests.submit(() -> {
				reloadThread.set(Thread.currentThread());
				reloadReady.countDown();
				allowReload.await();
				return browseList.sharedWithinBudget("types", count, 5000);
			});
			Future<Optional<Long>> other = requests.submit(() -> browseList.sharedWithinBudget("graphs", () -> 7L,
					5000));
			assertThat(other.get(5, TimeUnit.SECONDS)).as("another count runs on its own").contains(7L);
			assertThat(reloadReady.await(5, TimeUnit.SECONDS)).isTrue();
			allowReload.countDown();
			// Completing the unrelated request does not establish that the reload joined the first count.
			assertThat(awaitSharedCountWait(reloadThread.get(), 5, TimeUnit.SECONDS))
					.as("the reload joined the still-running count before it is released")
					.isTrue();
			assertThat(runs).hasValue(1);
			release.countDown();

			assertThat(first.get(5, TimeUnit.SECONDS)).contains(42L);
			assertThat(reload.get(5, TimeUnit.SECONDS)).contains(42L);
			assertThat(runs).as("the reload joined the running count").hasValue(1);
			assertThat(browseList.sharedWithinBudget("types", count, 5000)).as("a later request counts again")
					.contains(42L);
			assertThat(runs).hasValue(2);
		} finally {
			allowReload.countDown();
			release.countDown();
			requests.shutdownNow();
			browseList.shutdown();
		}
	}

	private static boolean awaitSharedCountWait(Thread thread, long timeout, TimeUnit unit)
			throws InterruptedException {
		long deadline = System.nanoTime() + unit.toNanos(timeout);
		while (System.nanoTime() < deadline) {
			boolean inSharedCount = false;
			for (StackTraceElement frame : thread.getStackTrace()) {
				inSharedCount |= frame.getClassName().equals(BrowseList.class.getName())
						&& frame.getMethodName().equals("sharedWithinBudget");
			}
			// The pre-call gate is an untimed await. Inside this application method, the only
			// timed wait is for the shared result, after waiter registration has completed.
			if (inSharedCount && thread.getState() == Thread.State.TIMED_WAITING) {
				return true;
			}
			TimeUnit.MILLISECONDS.sleep(1);
		}
		return false;
	}

	@Test
	void aSharedCountRunsOnUntilItsLastWaiterGivesUp() throws Exception {
		BrowseList browseList = new BrowseList(8);
		ExecutorService requests = Executors.newSingleThreadExecutor();
		CountDownLatch started = new CountDownLatch(1);
		CountDownLatch release = new CountDownLatch(1);
		CountDownLatch interrupted = new CountDownLatch(1);
		Callable<Long> count = () -> {
			started.countDown();
			try {
				release.await(10, TimeUnit.SECONDS);
				return 42L;
			} catch (InterruptedException e) {
				interrupted.countDown();
				throw e;
			}
		};
		try {
			Future<Optional<Long>> patient = requests.submit(() -> browseList.sharedWithinBudget("types", count,
					5000));
			assertThat(started.await(5, TimeUnit.SECONDS)).isTrue();
			assertThat(browseList.sharedWithinBudget("types", count, 50)).as("an impatient request gives up")
					.isEmpty();
			assertThat(interrupted.getCount()).as("the count still runs for the patient request").isEqualTo(1);
			release.countDown();
			assertThat(patient.get(5, TimeUnit.SECONDS)).contains(42L);

			CountDownLatch secondStarted = new CountDownLatch(1);
			CountDownLatch secondInterrupted = new CountDownLatch(1);
			assertThat(browseList.sharedWithinBudget("graphs", () -> {
				secondStarted.countDown();
				try {
					new CountDownLatch(1).await(10, TimeUnit.SECONDS);
					return 1L;
				} catch (InterruptedException e) {
					secondInterrupted.countDown();
					throw e;
				}
			}, 100)).isEmpty();
			assertThat(secondInterrupted.await(5, TimeUnit.SECONDS)).as("its only waiter gave up, so it is cancelled")
					.isTrue();
		} finally {
			release.countDown();
			requests.shutdownNow();
			browseList.shutdown();
		}
	}

	@Test
	void statementCountsAnswerTheRepositoryTheDefaultGraphAndEachGraph() throws Exception {
		Repository repository = new SailRepository(new MemoryStore());
		repository.init();
		BrowseList browseList = new BrowseList(() -> repository);
		try (RepositoryConnection connection = repository.getConnection()) {
			ValueFactory vf = connection.getValueFactory();
			IRI g1 = vf.createIRI("urn:g1");
			connection.add(vf.createIRI("urn:a"), RDFS.LABEL, vf.createLiteral("a"));
			connection.add(vf.createIRI("urn:b"), RDFS.LABEL, vf.createLiteral("b"), g1);
			connection.add(vf.createIRI("urn:c"), RDFS.LABEL, vf.createLiteral("c"), g1);

			BrowseList.StatementCounts counts = browseList.statementCounts(repository, List.of(g1), 2000);

			assertThat(counts.timedOut()).isFalse();
			assertThat(counts.values()).containsEntry(BrowseList.REPOSITORY, 3L)
					.containsEntry(BrowseList.DEFAULT_GRAPH, 1L)
					.containsEntry(BrowseList.key(g1), 2L);
		} finally {
			browseList.shutdown();
			repository.shutDown();
		}
	}
}
